import { Bot, Webhook } from "lucide-react";
import { cn } from "@/components/lib/utils.js";
import { useZCodeIntl } from "@/i18n/IntlProvider.js";

// 渠道图标（附录C §4.1）：官方 telegram/weixin/dingding/discord/wecom 用 png 资产、
// feishu/lark 用内联 base64。这里统一内联 data URI，避免 ui 包被不同宿主打包时丢失静态资产路径。
const TELEGRAM_ICON_DATA_URI =
  "data:image/png;base64,";
const WEIXIN_ICON_DATA_URI =
  "data:image/png;base64,";
const FEISHU_ICON_DATA_URI =
  "data:image/png;base64,";
const DINGDING_ICON_DATA_URI =
  "data:image/png;base64,";
const DISCORD_ICON_DATA_URI =
  "data:image/png;base64,";
const WECOM_ICON_DATA_URI =
  "data:image/png;base64,";
const CHANNEL_ICON_DATA_URIS: Record<string, string | undefined> = {
  telegram: TELEGRAM_ICON_DATA_URI,
  weixin: WEIXIN_ICON_DATA_URI,
  feishu: FEISHU_ICON_DATA_URI,
  lark: FEISHU_ICON_DATA_URI,
  dingding: DINGDING_ICON_DATA_URI,
  discord: DISCORD_ICON_DATA_URI,
  wecom: WECOM_ICON_DATA_URI,
};

/** 区域徽章（附录C §1.2 `Prn`）：Lark=全球、飞书=中国。 */
export function resolveBotRegionTagKey(provider: string): string | null {
  switch (provider) {
    case "lark":
      return "login.oauth.regionTag.zai";
    case "feishu":
      return "login.oauth.regionTag.bigmodel";
    default:
      return null;
  }
}

export function BotChannelIcon({ provider, className }: { provider: string; className?: string }) {
  const iconSrc = CHANNEL_ICON_DATA_URIS[provider];
  if (iconSrc) {
    return (
      <img
        src={iconSrc}
        alt=""
        aria-hidden="true"
        className={cn("size-4 object-contain", className)}
      />
    );
  }
  if (provider === "webhook") {
    return <Webhook className={cn("size-4", className)} />;
  }
  return <Bot className={cn("size-4", className)} />;
}

/** 渠道名 + 区域徽章（列表项与新建网格共用）。 */
export function BotChannelLabel({
  provider,
  className,
  nameClassName,
}: {
  provider: string;
  className?: string;
  nameClassName?: string;
}) {
  const { intl } = useZCodeIntl();
  const regionTagKey = resolveBotRegionTagKey(provider);
  return (
    <span className={cn("inline-flex min-w-0 items-center gap-1.5", className)}>
      <span className={cn("min-w-0 truncate", nameClassName)}>
        {intl.formatMessage({ id: `bots.channel.${provider}` })}
      </span>
      {regionTagKey ? (
        <span className="inline-flex h-5 shrink-0 items-center rounded-full border border-border px-2 text-ui-xs font-medium leading-none text-foreground-subtle">
          {intl.formatMessage({ id: regionTagKey })}
        </span>
      ) : null}
    </span>
  );
}
